fn boxed_dyn_type(trait_name: &str) -> RustType {
    RustType::Generic {
        base: "Box".to_string(),
        args: vec![RustType::DynTrait(trait_name.to_string())],
    }
}

fn unknown_api_constraints(
    java_ty: &JavaType,
    facts: &EffectiveFacts<'_>,
) -> Vec<SignatureConstraint> {
    signature_boundary_policy_with_effective_facts(
        SignatureBoundaryKind::UnknownApi,
        java_ty,
        facts,
    )
    .constraints
}

#[test]
fn slot_shape_keeps_string_ownership_and_view_as_separate_axes() {
    let mut shape = RustSlotShape::conservative(JavaType::String);
    assert_eq!(shape.ownership, OwnershipShape::Owned);
    assert_eq!(shape.view, ViewShape::Native);
    assert_eq!(rust_type_for_slot(&shape), RustType::String);

    shape.ownership = OwnershipShape::SharedBorrow;
    shape.view = ViewShape::Str;
    assert_eq!(
        rust_type_for_slot(&shape),
        RustType::Ref {
            mutable: false,
            lifetime: None,
            inner: Box::new(RustType::Raw("str".to_string()))
        }
    );
}

#[test]
fn slot_shape_projects_arrays_and_primitives_without_type_specific_ownership_variants() {
    let int_shape = RustSlotShape::conservative(JavaType::Primitive(PrimitiveType::Int));
    assert_eq!(int_shape.ownership, OwnershipShape::CopyValue);
    assert_eq!(int_shape.view, ViewShape::Native);
    assert_eq!(rust_type_for_slot(&int_shape), RustType::I32);

    let mut array_shape = RustSlotShape::conservative(JavaType::Array(Box::new(JavaType::String)));
    array_shape.ownership = OwnershipShape::SharedBorrow;
    array_shape.view = ViewShape::Slice;
    assert_eq!(
        rust_type_for_slot(&array_shape),
        RustType::Ref {
            mutable: false,
            lifetime: None,
            inner: Box::new(RustType::Slice(Box::new(RustType::String)))
        }
    );
}

#[test]
fn rust_crate_mapped_external_slots_render_facade_type_identity() {
    let mut facts = FactSet::default();
    facts.external_library_packs.push(ExternalLibraryPackFact {
        pack_name: "sqlite".to_string(),
        package_prefix: "java.sql.Connection".to_string(),
        mode: ExternalLibraryMode::RustCrateMapping,
        coverage: ExternalApiCoverage::Mapped,
        rust_target: Some("sqlite_facade".to_string()),
        provenance: FactProvenance::ExternalLibraryPack,
    });
    facts.external_library_packs.push(ExternalLibraryPackFact {
        pack_name: "hdf5".to_string(),
        package_prefix: "HDF5File".to_string(),
        mode: ExternalLibraryMode::RustCrateMapping,
        coverage: ExternalApiCoverage::Mapped,
        rust_target: Some("hdf5_facade".to_string()),
        provenance: FactProvenance::ExternalLibraryPack,
    });

    let sqlite_connection_ty = rust_type_for_slot_with_facts(
        &RustSlotShape::conservative(JavaType::Named {
            name: "java.sql.Connection".to_string(),
            args: Vec::new(),
        }),
        &facts,
    );
    assert_eq!(
        sqlite_connection_ty,
        RustType::Named("sqlite_facade::Connection".to_string())
    );
    assert_eq!(
        emit::emit_type(&sqlite_connection_ty),
        "sqlite_facade::Connection"
    );
    assert_eq!(
        rust_type_for_slot_with_facts(
            &RustSlotShape::conservative(JavaType::Named {
                name: "HDF5File".to_string(),
                args: Vec::new(),
            }),
            &facts
        ),
        RustType::Named("hdf5_facade::HDF5File".to_string())
    );
    let sqlite_result_ty = rust_type_for_slot_with_facts(
        &RustSlotShape::conservative(JavaType::Named {
            name: "java.sql.Connection".to_string(),
            args: vec![JavaType::String],
        }),
        &facts,
    );
    assert_eq!(
        sqlite_result_ty,
        RustType::Generic {
            base: "sqlite_facade::Connection".to_string(),
            args: vec![RustType::String],
        }
    );
    assert_eq!(
        emit::emit_type(&sqlite_result_ty),
        "sqlite_facade::Connection<String>"
    );
}

#[test]
fn generic_facade_interface_slot_erases_arguments_without_any_handoff() {
    let comparator_ty = JavaType::Named {
        name: "Comparator".to_string(),
        args: vec![JavaType::Named {
            name: "VariantContext".to_string(),
            args: Vec::new(),
        }],
    };
    let mut shape = RustSlotShape::for_storage(optional_java_type(comparator_ty.clone()));
    shape.dispatch = DispatchShape::ErasedObject;
    shape.view = ViewShape::ErasedObjectView;

    assert_eq!(
        rust_type_for_java_type_with_facts(&comparator_ty, &FactSet::default()),
        RustType::Named("Comparator".to_string())
    );
    assert_eq!(
        rust_type_for_slot_with_facts(&shape, &FactSet::default()),
        RustType::Option(Box::new(RustType::Named("Comparator".to_string())))
    );
}

#[test]
fn rust_crate_mapped_static_external_owners_render_facade_paths() {
    let facts = parse_external_pack_manifest(
        r#"
external-pack arrow VectorSchemaRoot rust-crate-mapping mapped target=arrow_facade
external-pack-api arrow VectorSchemaRoot of mapped getter read-only definitely-non-null args=1 return=VectorSchemaRoot rust=of
external-pack sql driver_manager rust-crate-mapping mapped target=sqlite_facade
external-pack-api sql driver_manager getConnection mapped getter read-only definitely-non-null args=1 return=Connection rust=get_connection
external-pack-api sql driver_manager getConnection mapped getter read-only definitely-non-null args=2 return=Connection rust=get_connection_with_properties
external-pack sql java.sql.DriverManager rust-crate-mapping mapped target=sqlite_facade
external-pack-api sql java.sql.DriverManager getConnection mapped getter read-only definitely-non-null args=2 return=Connection rust=get_connection_with_properties
"#,
    )
    .facts;

    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("VectorSchemaRoot".to_string())),
            "of",
            1,
            None,
            &facts,
            &TypeEnv::default(),
        ),
        CallTargetPlan::StaticOwner {
            ref owner,
            ref rust_name,
        } if owner == "arrow_facade::VectorSchemaRoot" && rust_name == "of"
    ));
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("driver_manager".to_string())),
            "getConnection",
            1,
            None,
            &facts,
            &TypeEnv::default(),
        ),
        CallTargetPlan::StaticOwner {
            ref owner,
            ref rust_name,
        } if owner == "sqlite_facade::driver_manager" && rust_name == "get_connection"
    ));
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("driver_manager".to_string())),
            "getConnection",
            2,
            None,
            &facts,
            &TypeEnv::default(),
        ),
        CallTargetPlan::StaticOwner {
            ref owner,
            ref rust_name,
        } if owner == "sqlite_facade::driver_manager" && rust_name == "get_connection_with_properties"
    ));

    let mut imported_types = TypeEnv::new();
    imported_types.insert_static_type_alias("DriverManager", "java.sql.DriverManager");
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("DriverManager".to_string())),
            "getConnection",
            2,
            None,
            &facts,
            &imported_types,
        ),
        CallTargetPlan::StaticOwner {
            ref owner,
            ref rust_name,
        } if owner == "sqlite_facade::DriverManager" && rust_name == "get_connection_with_properties"
    ));
}

