#[test]
fn anonymous_external_facade_return_keeps_declared_concrete_shape_for_internal_method() {
    let source = r#"
class AnonymousFeatureReaderFactory {
    FeatureReader<String> use() {
        FeatureReader<String> reader = reader();
        return reader;
    }

    private FeatureReader<String> reader() {
        return new FeatureReader<String>() {
            public void close() {}
        };
    }
}
"#;
    let facts = new_java2rust::external_packs::htsjdk_tribble_feature_pack_facts();
    let parsed = parse_java_source(source);
    let resolved = resolve_program_with_source_program_and_facts(
        &parsed.program,
        parsed.diagnostics,
        &parsed.program,
        &facts,
    );
    let semantic = analyze_program(&resolved.program, &resolved.facts, &facts);
    let representations = plan_representations(&resolved.program, &semantic.facts);
    let signatures = new_java2rust::signature::solve_signatures_with_facts_and_support_context(
        &resolved.program,
        &representations,
        &semantic.usage,
        &semantic.facts,
        &resolved.program,
    );
    let reader_shape = signatures
        .method_return_shape_by_rust_name("AnonymousFeatureReaderFactory", "reader")
        .expect("reader return should be planned");
    assert_eq!(reader_shape.dispatch, DispatchShape::Concrete);
    assert_eq!(reader_shape.view, ViewShape::Native);

    let translation = translate_source_with_facts(source, &facts);

    assert!(
        translation
            .rust
            .contains("pub fn reader(&self) -> FeatureReader")
            && translation.rust.contains("return Default::default();")
            && translation
                .rust
                .contains("let reader: FeatureReader = self.reader();")
            && !translation.rust.contains("downcast::<FeatureReader>()")
            && !translation.rust.contains("invalid Java cast"),
        "anonymous external facade returns should keep declared concrete shape:\n{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "anonymous_external_facade_return_keeps_declared_concrete_sha",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

#[test]
fn duplicate_local_names_use_scoped_occurrence_shape_before_map_insert_conversion() {
    let source = r#"
class DuplicateReaderLocalMapPut {
    FeatureReader<String> reader() {
        return new FeatureReader<String>() {
            public void close() {}
        };
    }

    void put(java.util.Map<String, FeatureReader<String>> map, boolean flag) {
        if (flag) {
            FeatureReader<String> reader;
        }
        FeatureReader<String> reader = reader();
        map.put("x", reader);
    }
}
"#;
    let facts = new_java2rust::external_packs::htsjdk_tribble_feature_pack_facts();

    let translation = translate_source_with_facts(source, &facts);

    assert!(
        translation
            .rust
            .contains("let reader: FeatureReader = self.reader();"),
        "second reader declaration should keep the concrete facade shape:\n{}",
        translation.rust
    );
    assert!(
        !translation.rust.contains("downcast::<FeatureReader>()")
            && !translation.rust.contains("invalid Java cast"),
        "map value conversion should see the concrete reader occurrence, not the earlier erased declaration:\n{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "duplicate_local_names_use_scoped_occurrence_shape_before_map",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

#[test]
fn representation_plan_applies_user_closed_enum_hierarchy_override() {
    let parsed = parse_java_source(
        r#"
interface Expr {}
class Add implements Expr {}
class Num implements Expr {}
"#,
    );
    let resolved = resolve_program(&parsed.program, parsed.diagnostics);
    let mut facts = resolved.facts.clone();
    facts.hierarchy_overrides.push(HierarchyOverride {
        type_name: "Expr".to_string(),
        strategy: HierarchyStrategy::ClosedEnum {
            enum_name: "ExprValue".to_string(),
            variants: vec!["Add".to_string(), "Num".to_string()],
        },
        provenance: FactProvenance::UserOverride,
    });

    let representations = plan_representations(&resolved.program, &facts);

    assert_eq!(
        representations.representation_for(&JavaType::Named {
            name: "Expr".to_string(),
            args: Vec::new(),
        }),
        ObjectRepresentation::ClosedEnum {
            enum_name: "ExprValue".to_string(),
            variants: vec!["Add".to_string(), "Num".to_string()],
        }
    );
    assert_eq!(
        representations.dispatch_for(&JavaType::Named {
            name: "Expr".to_string(),
            args: Vec::new(),
        }),
        DispatchShape::ClosedEnum {
            enum_name: "ExprValue".to_string(),
        }
    );
    assert_eq!(
        representations.direct_subtypes_of("Expr"),
        ["Add".to_string(), "Num".to_string()].as_slice()
    );
    assert_eq!(
        representations
            .type_representation("Expr")
            .unwrap()
            .provenance,
        RepresentationProvenance::UserOverride
    );
    assert!(
        representations
            .diagnostics_for_program(&resolved.program)
            .iter()
            .all(|diagnostic| diagnostic.code != "representation_override_conflict")
    );
}

#[test]
fn representation_lowering_owns_non_struct_type_emission() {
    let parsed = parse_java_source(
        r#"
interface Expr {}
class Add implements Expr {}
class Num implements Expr {}
"#,
    );
    let resolved = resolve_program(&parsed.program, parsed.diagnostics);
    let mut facts = FactSet::default();
    facts.hierarchy_overrides.push(HierarchyOverride {
        type_name: "Expr".to_string(),
        strategy: HierarchyStrategy::ClosedEnum {
            enum_name: "ExprValue".to_string(),
            variants: vec!["Add".to_string(), "Num".to_string()],
        },
        provenance: FactProvenance::UserOverride,
    });

    let representations = plan_representations(&resolved.program, &facts);
    let signatures = solve_signatures_with_facts(
        &resolved.program,
        &representations,
        &analyze_usage(&resolved.program),
        &facts,
    );
    let expr_ty = resolved
        .program
        .types
        .iter()
        .find(|ty| ty.name == "Expr")
        .unwrap();
    let add_ty = resolved
        .program
        .types
        .iter()
        .find(|ty| ty.name == "Add")
        .unwrap();

    assert_eq!(
        type_emission_for_with_facts(&representations, expr_ty, &signatures, &FactSet::default()),
        RepresentationTypeEmission::RawRustItem(
            "#[derive(Clone, PartialEq)]\npub enum ExprValue {\n    Add(Add),\n    Num(Num),\n}"
                .to_string()
        )
    );
    assert_eq!(
        raw_type_item_for_with_facts(&representations, expr_ty, &signatures, &facts),
        Some(
            "#[derive(Clone, PartialEq)]\npub enum ExprValue {\n    Add(Add),\n    Num(Num),\n}"
                .to_string()
        )
    );
    assert_eq!(
        type_emission_for_with_facts(&representations, add_ty, &signatures, &FactSet::default()),
        RepresentationTypeEmission::LowerAsConcreteStruct
    );
    assert_eq!(
        raw_type_item_for_with_facts(&representations, add_ty, &signatures, &facts),
        None
    );
    let enum_parsed = parse_java_source(
        r#"
class Holder {
    enum Type {
        SNP,
        INDEL
    }
}
"#,
    );
    let enum_resolved = resolve_program(&enum_parsed.program, enum_parsed.diagnostics);
    let enum_representations = plan_representations(&enum_resolved.program, &FactSet::default());
    let enum_signatures = solve_signatures_with_facts(
        &enum_resolved.program,
        &enum_representations,
        &analyze_usage(&enum_resolved.program),
        &FactSet::default(),
    );
    let holder_ty = enum_resolved
        .program
        .types
        .iter()
        .find(|ty| ty.name == "Holder")
        .unwrap();
    let enum_ty = holder_ty
        .members
        .iter()
        .find_map(|member| match member {
            Member::Type(ty) if ty.name.ends_with(".Type") => Some(ty),
            _ => None,
        })
        .unwrap();
    assert_eq!(rust_enum_variant_name_from_parsed_constant("s_n_p"), "SNP");
    assert!(matches!(
        enum_representations
            .type_representation("Holder.Type")
            .map(|representation| &representation.representation),
        Some(ObjectRepresentation::JavaEnum { enum_name, variants })
            if enum_name == "Holder.Type" && variants == &vec!["SNP".to_string(), "INDEL".to_string()]
    ));
    let RepresentationTypeEmission::RawRustItem(enum_item) = type_emission_for_with_facts(
        &enum_representations,
        enum_ty,
        &enum_signatures,
        &FactSet::default(),
    ) else {
        panic!("Java enum should emit a raw Rust enum item");
    };
    assert!(enum_item.contains("pub enum Holder_Type"));
    assert!(enum_item.contains("SNP"));
    assert!(enum_item.contains("INDEL"));
    assert!(enum_item.contains("impl Default for Holder_Type"));
    assert!(enum_item.contains("pub fn values() -> Vec<Self>"));
    assert!(enum_item.contains("pub fn value_of<T: AsRef<str>>(name: T) -> Self"));
    assert!(enum_item.contains("pub fn ordinal(&self) -> i32"));
    assert!(enum_item.contains("impl std::fmt::Display for Holder_Type"));
}

