#[test]
fn external_constant_facade_shells_are_defaultable_for_constructor_fallbacks() {
    let mut facts = FactSet::default();
    facts.external_field_facts.push(ExternalFieldFact {
        field: FactFieldKey {
            type_name: "ExternalHeader".to_string(),
            field_name: "HEADER_INDICATOR".to_string(),
        },
        field_type: Some(JavaType::String),
        field_kind: ExternalFieldKind::StaticFinal,
        provenance: FactProvenance::ExternalLibraryPack,
    });
    facts
        .external_constructor_facts
        .push(ExternalConstructorFact {
            type_name: "ExternalHeader".to_string(),
            arg_types: vec![JavaType::String, JavaType::Primitive(PrimitiveType::Int)],
            provenance: FactProvenance::ExternalLibraryPack,
        });

    let translation = translate_source_with_facts(
        r#"
class ExternalConstantConstructorCaller {
    ExternalHeader make(String name, int count) {
        return new ExternalHeader(name, count);
    }

    String marker() {
        return ExternalHeader.HEADER_INDICATOR;
    }
}
"#,
        &facts,
    );

    assert!(
        translation
            .rust
            .contains("#[derive(Clone, Debug, Default)]\npub struct ExternalHeader;"),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("pub fn new(_arg0: String, _arg1: i32) -> Self { Default::default() }"),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("pub const HEADER_INDICATOR: &'static str = \"HEADER_INDICATOR\";"),
        "{}",
        translation.rust
    );
    let stdlib_source = include_str!("../src/stdlib.rs");
    let support_items_source = stdlib_source
        .split("pub fn external_static_string_constant_support_items_with_context_programs_and_declared_owners")
        .nth(1)
        .and_then(|tail| {
            tail.split("fn collect_static_constant_field_support_types")
                .next()
        })
        .expect("external static string support item helper should remain discoverable");
    assert!(
        support_items_source.contains("RustItem::Struct")
            && support_items_source.contains("RustStruct")
            && support_items_source.contains("is_unit: true")
            && !support_items_source.contains("RustItem::Raw(format!"),
        "external static string placeholder structs should use structured unit struct items"
    );

    cargo_check_generated_modules(
        "external_constant_facade_shells_are_defaultable_for_construc",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

