#[test]
fn call_plan_recovers_normalized_static_utility_owner_receivers() {
    let facts = new_java2rust::external_packs::broad_hellbender_utils_pack_facts();
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("i_o_utils".to_string())),
            "getPath",
            1,
            None,
            &facts,
            &new_java2rust::types::TypeEnv::default(),
        ),
        CallTargetPlan::StaticOwner {
            owner,
            rust_name
        } if owner == "IOUtils" && rust_name == "get_path"
    ));

    let mut shadowed_types = TypeEnv::new();
    shadowed_types.insert_local("i_o_utils", JavaType::Unknown("LocalIOUtils".to_string()));
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("i_o_utils".to_string())),
            "getPath",
            1,
            None,
            &facts,
            &shadowed_types,
        ),
        CallTargetPlan::FallbackReceiver { .. }
    ));

    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("math".to_string())),
            "pow",
            2,
            None,
            &FactSet::default(),
            &TypeEnv::default(),
        ),
        CallTargetPlan::StaticOwner {
            owner,
            rust_name
        } if owner == "Math" && rust_name == "pow"
    ));
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("double".to_string())),
            "isInfinite",
            1,
            None,
            &FactSet::default(),
            &TypeEnv::default(),
        ),
        CallTargetPlan::StaticOwner {
            owner,
            rust_name
        } if owner == "Double" && rust_name == "is_infinite"
    ));
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("system".to_string())),
            "arraycopy",
            5,
            None,
            &FactSet::default(),
            &TypeEnv::default(),
        ),
        CallTargetPlan::StaticOwner {
            owner,
            rust_name
        } if owner == "System" && rust_name == "arraycopy"
    ));
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("external_util".to_string())),
            "consume",
            1,
            None,
            &FactSet::default(),
            &TypeEnv::default(),
        ),
        CallTargetPlan::StaticOwner {
            owner,
            rust_name
        } if owner == "ExternalUtil" && rust_name == "consume"
    ));
    assert!(matches!(
        plan_call_target_with_facts_and_arity(
            Some(&Expr::Var("foo".to_string())),
            "toString",
            0,
            None,
            &FactSet::default(),
            &TypeEnv::default(),
        ),
        CallTargetPlan::FallbackReceiver { .. }
    ));

    let mut imported_types = TypeEnv::new();
    imported_types.insert_static_type_alias("external_utility", "external.lib.ExternalUtility");
    assert!(matches!(
        plan_call_target_with_facts(
            Some(&Expr::Var("external_utility".to_string())),
            "readValue",
            None,
            &FactSet::default(),
            &imported_types,
        ),
        CallTargetPlan::StaticOwner {
            owner,
            rust_name
        } if owner == "ExternalLibExternalUtility" && rust_name == "read_value"
    ));

    imported_types.insert_local(
        "external_utility",
        JavaType::Unknown("LocalExternalUtility".to_string()),
    );
    assert!(matches!(
        plan_call_target_with_facts(
            Some(&Expr::Var("external_utility".to_string())),
            "readValue",
            None,
            &FactSet::default(),
            &imported_types,
        ),
        CallTargetPlan::FallbackReceiver { .. }
    ));

    let mut static_import_types = TypeEnv::new();
    static_import_types.insert_static_member_import("readValue", "external.lib.StaticUtility");
    assert!(matches!(
        plan_call_target_with_facts(
            None,
            "readValue",
            None,
            &FactSet::default(),
            &static_import_types,
        ),
        CallTargetPlan::StaticOwner {
            owner,
            rust_name
        } if owner == "ExternalLibStaticUtility" && rust_name == "read_value"
    ));
    assert!(matches!(
        plan_call_target_with_facts(
            None,
            "localValue",
            None,
            &FactSet::default(),
            &static_import_types,
        ),
        CallTargetPlan::FallbackFree { rust_name } if rust_name == "local_value"
    ));
}

