#[test]
fn conversion_plan_owns_cast_and_instanceof_shape_pairing_before_lowering() {
    let parsed = parse_java_source(
        r#"
interface Animal {}
class Dog implements Animal {}
"#,
    );
    let resolved = resolve_program(&parsed.program, parsed.diagnostics);
    let mut facts = resolved.facts.clone();
    facts.hierarchy_overrides.push(HierarchyOverride {
        type_name: "Animal".to_string(),
        strategy: HierarchyStrategy::ClosedEnum {
            enum_name: "AnimalValue".to_string(),
            variants: vec!["Dog".to_string()],
        },
        provenance: FactProvenance::UserOverride,
    });
    let representations = plan_representations(&resolved.program, &facts);
    let ctx = ExprShapeContext {
        signatures: None,
        representations: Some(&representations),
        facts: None,
    };
    let fact_ctx = ExprShapeContext {
        signatures: None,
        representations: Some(&representations),
        facts: Some(&facts),
    };
    let mut env = ShapeEnv::new();
    env.insert_local(
        "dog",
        JavaType::Named {
            name: "Dog".to_string(),
            args: Vec::new(),
        },
    );
    let animal_ty = JavaType::Named {
        name: "Animal".to_string(),
        args: Vec::new(),
    };
    env.insert_local_shape(
        "animal",
        value_shape_for_java_type(&representations, animal_ty.clone()),
    );
    let cast_plan = plan_cast_conversion(&parse_expr("dog"), &animal_ty, &env, ctx);
    assert_eq!(
        cast_plan.target.dispatch,
        DispatchShape::ClosedEnum {
            enum_name: "AnimalValue".to_string()
        }
    );
    assert_eq!(
        cast_plan.coercion.coercions(),
        vec![Coercion::WrapClosedEnum {
            enum_name: "AnimalValue".to_string(),
            variant_name: "Dog".to_string(),
        }]
    );
    assert_eq!(
        cast_plan.semantics,
        JavaCastSemanticsPolicy::ReferenceUpcast
    );
    assert_eq!(
        apply_cast_conversion(RustExpr::Var("dog".to_string()), &cast_plan),
        RustExpr::Call {
            function: Box::new(RustExpr::path(["AnimalValue", "Dog"])),
            args: vec![RustExpr::Var("dog".to_string())],
        }
    );
    let mut borrowed_env = ShapeEnv::new();
    let mut borrowed_dog_shape = value_shape_for_java_type(
        &representations,
        JavaType::Named {
            name: "Dog".to_string(),
            args: Vec::new(),
        },
    );
    borrowed_dog_shape.ownership = OwnershipShape::SharedBorrow;
    borrowed_env.insert_local_shape("dog", borrowed_dog_shape);
    let borrowed_cast_plan =
        plan_cast_conversion(&parse_expr("dog"), &animal_ty, &borrowed_env, ctx);
    assert!(
        borrowed_cast_plan
            .coercion
            .coercions()
            .iter()
            .any(|coercion| matches!(coercion, Coercion::CloneRecovery { .. })),
        "{borrowed_cast_plan:?}"
    );
    assert_eq!(
        apply_cast_conversion(RustExpr::Var("dog".to_string()), &borrowed_cast_plan),
        RustExpr::Raw(
            "AnimalValue::Dog(dog.clone()/* TODO(translation): validate added clone */)"
                .to_string()
        )
    );

    let erased_facts = new_java2rust::external_packs::htsjdk_tribble_feature_pack_facts();
    let erased_parsed = parse_java_source("class CastOwner {}");
    let erased_resolved = resolve_program(&erased_parsed.program, erased_parsed.diagnostics);
    let erased_representations = plan_representations(&erased_resolved.program, &erased_facts);
    let feature_reader_ty = JavaType::Named {
        name: "FeatureReader".to_string(),
        args: vec![JavaType::String],
    };
    let mut erased_env = ShapeEnv::new();
    let mut concrete_reader_shape = RustSlotShape::conservative(feature_reader_ty.clone());
    concrete_reader_shape.dispatch = DispatchShape::Concrete;
    concrete_reader_shape.view = ViewShape::Native;
    erased_env.insert_local_shape("reader", concrete_reader_shape);
    let concrete_cast_plan = plan_cast_conversion(
        &parse_expr("reader"),
        &JavaType::Named {
            name: "FeatureReader".to_string(),
            args: Vec::new(),
        },
        &erased_env,
        ExprShapeContext {
            signatures: None,
            representations: Some(&erased_representations),
            facts: Some(&erased_facts),
        },
    );
    assert_eq!(
        concrete_cast_plan.semantics,
        JavaCastSemanticsPolicy::Identity
    );
    assert_eq!(concrete_cast_plan.target.dispatch, DispatchShape::Concrete);

    let mut list_env = ShapeEnv::new();
    let typed_list_ty = JavaType::Named {
        name: "List".to_string(),
        args: vec![JavaType::String],
    };
    let mut typed_list_shape = RustSlotShape::conservative(typed_list_ty.clone());
    typed_list_shape.dispatch = DispatchShape::Concrete;
    typed_list_shape.view = ViewShape::Native;
    list_env.insert_local_shape("lines", typed_list_shape);
    let raw_list_cast_plan = plan_cast_conversion(
        &parse_expr("lines"),
        &JavaType::Named {
            name: "List".to_string(),
            args: Vec::new(),
        },
        &list_env,
        ExprShapeContext {
            signatures: None,
            representations: Some(&erased_representations),
            facts: Some(&erased_facts),
        },
    );
    assert_eq!(
        raw_list_cast_plan.semantics,
        JavaCastSemanticsPolicy::Identity
    );
    assert_eq!(raw_list_cast_plan.target.java_ty, typed_list_ty);
    assert_eq!(
        apply_cast_conversion(RustExpr::Var("lines".to_string()), &raw_list_cast_plan),
        RustExpr::Var("lines".to_string())
    );
    let raw_list_expr = Expr::Cast {
        ty: JavaType::Named {
            name: "List".to_string(),
            args: Vec::new(),
        },
        expr: Box::new(parse_expr("lines")),
    };
    let raw_list_actual = actual_shape_for_slot_expr_with_slot(
        &raw_list_expr,
        &list_env,
        ExprShapeContext {
            signatures: None,
            representations: Some(&erased_representations),
            facts: Some(&erased_facts),
        },
        &new_java2rust::conversion_plan::assignment_slot(raw_list_cast_plan.target.clone()),
    );
    assert_eq!(raw_list_actual.java_ty, typed_list_ty);

    let dog_ty = JavaType::Named {
        name: "Dog".to_string(),
        args: Vec::new(),
    };
    let instanceof_plan = plan_instanceof(&parse_expr("animal"), &dog_ty, &env, ctx);
    assert_eq!(
        instanceof_plan.check,
        InstanceOfCheck::ClosedEnumVariant {
            enum_name: "AnimalValue".to_string(),
            variant_name: "Dog".to_string(),
        }
    );
    let instanceof_expr = apply_instanceof(RustExpr::Var("animal".to_string()), &instanceof_plan);
    assert_eq!(
        emit::emit_expr(&instanceof_expr),
        "matches!(animal, AnimalValue::Dog(_))"
    );
    assert!(matches!(
        instanceof_expr,
        RustExpr::MacroCall { macro_name, args }
            if macro_name == "matches"
                && matches!(
                    args.as_slice(),
                    [RustExpr::Var(name), RustExpr::Raw(pattern)]
                        if name == "animal" && pattern == "AnimalValue::Dog(_)"
                )
    ));

    let interface_instanceof_plan = plan_instanceof(&parse_expr("dog"), &animal_ty, &env, fact_ctx);
    assert_eq!(interface_instanceof_plan.check, InstanceOfCheck::AlwaysTrue);
}

#[test]
fn conversion_plan_uses_target_slot_shape_for_unresolved_unknown_calls() {
    let unresolved_call = Expr::Call {
        receiver: None,
        name: "defaultNames".to_string(),
        args: Vec::new(),
        resolved: None,
    };
    let target_shape = RustSlotShape::for_storage(JavaType::Named {
        name: "Set".to_string(),
        args: vec![JavaType::String],
    });
    assert_eq!(
        actual_shape_for_slot_expr_with_slot(
            &unresolved_call,
            &ShapeEnv::new(),
            ExprShapeContext::default(),
            &argument_slot(target_shape.clone()),
        ),
        target_shape
    );

    let explicit_cast = Expr::Cast {
        ty: JavaType::String,
        expr: Box::new(unresolved_call),
    };
    assert_ne!(
        actual_shape_for_slot_expr_with_slot(
            &explicit_cast,
            &ShapeEnv::new(),
            ExprShapeContext::default(),
            &argument_slot(target_shape.clone()),
        ),
        target_shape
    );
}

#[test]
fn lower_consumes_cast_and_instanceof_plans_without_rechecking_representation_facts() {
    let lower_source = include_str!("../src/lower.rs");
    let cast_instanceof_branch = lower_source
        .rsplit("Expr::Cast { ty, expr } =>")
        .next()
        .and_then(|tail| tail.split("Expr::ClassLiteral(ty)").next())
        .expect("cast and instanceof lowering branch should be present");
    let conversion_source = include_str!("../src/conversion_plan.rs");
    let lowering_source = include_str!("../src/conversion_lowering.rs");

    assert!(conversion_source.contains("project_java_value_shape(ctx.representations"));
    assert!(conversion_source.contains("ctx.facts.unwrap_or"));
    assert!(
        conversion_source.contains("plan_instanceof_check_with_facts(&actual, &target, facts)")
    );
    assert!(
        conversion_source
            .contains("java_cast_semantics_policy_with_facts(&actual, &target, &coercion, facts)")
    );

    assert!(cast_instanceof_branch.contains("plan_cast_conversion_from_actual("));
    assert!(cast_instanceof_branch.contains("apply_cast_conversion("));
    assert!(cast_instanceof_branch.contains("plan_instanceof("));
    assert!(cast_instanceof_branch.contains("apply_instanceof("));
    assert!(
        cast_instanceof_branch.contains("lower_expr_with_refinements(expr, env, ctx, refinements)")
    );
    assert!(cast_instanceof_branch.contains("representations: Some(ctx.representations)"));
    assert!(cast_instanceof_branch.contains("facts: Some(ctx.facts)"));
    assert!(!cast_instanceof_branch.contains("ObjectRepresentation"));
    assert!(!cast_instanceof_branch.contains("representation_for("));
    assert!(!cast_instanceof_branch.contains("dispatch_for("));
    assert!(!cast_instanceof_branch.contains("HierarchyStrategy"));
    assert!(!cast_instanceof_branch.contains("hierarchy_subtype_policy"));
    assert!(!cast_instanceof_branch.contains("reachable_hierarchy_edges"));
    assert!(!cast_instanceof_branch.contains("type_capability_overrides"));
    assert!(!cast_instanceof_branch.contains("instanceof_target_policy"));
    assert!(!cast_instanceof_branch.contains("plan_instanceof_check"));
    assert!(!cast_instanceof_branch.contains("JavaCastSemanticsPolicy"));
    assert!(!cast_instanceof_branch.contains("java_cast_semantics_policy"));
    assert!(!cast_instanceof_branch.contains("InvalidCastPolicy"));

    assert!(lowering_source.contains("apply_shape_coercion_plan(expr, &plan.coercion)"));
    assert!(lowering_source.contains("instanceof_check_projection(expr, &plan.check)"));
    assert!(!lowering_source.contains("ObjectRepresentation"));
    assert!(!lowering_source.contains("HierarchyStrategy"));
    assert!(!lowering_source.contains("hierarchy_subtype_policy"));
    assert!(!lowering_source.contains("java_cast_semantics_policy"));
}

#[test]
fn signature_plan_owns_field_param_and_return_shapes_before_lowering() {
    let parsed = parse_java_source(
        r#"
class Holder {
    String name;
    Holder(String name) { this.name = name; }
    public String echo(String value) { return value; }
}
"#,
    );
    let resolved = resolve_program(&parsed.program, parsed.diagnostics);
    let representations = plan_representations(&resolved.program, &resolved.facts);
    let usage = analyze_usage(&resolved.program);
    let signatures = solve_signatures(&resolved.program, &representations, &usage);
    let ty = &resolved.program.types[0];
    let method = ty
        .members
        .iter()
        .find_map(|member| match member {
            new_java2rust::java_ir::Member::Method(method) => Some(method),
            _ => None,
        })
        .unwrap();
    let ctor = ty
        .members
        .iter()
        .find_map(|member| match member {
            new_java2rust::java_ir::Member::Constructor(ctor) => Some(ctor),
            _ => None,
        })
        .unwrap();

    let field_shape = signatures.field_shape("Holder", "name").unwrap();
    assert_eq!(field_shape.java_ty, JavaType::String);
    assert_eq!(field_shape.mutability, MutabilityShape::Mutable);
    assert_eq!(
        field_shape_constraints(),
        vec![SignatureConstraint::StorageSlot]
    );
    assert!(signatures.field_shape("Holder", "missing").is_none());

    let method_signature = signatures.method_signature(ty, method).unwrap();
    assert_eq!(method_signature.params[0].java_ty, JavaType::String);
    assert_eq!(
        signatures.method_param_plans(ty, method).unwrap()[0].java_ty,
        JavaType::String
    );
    assert_eq!(
        signatures.constructor_param_plans(ty, ctor).unwrap()[0].java_ty,
        JavaType::String
    );
    assert_eq!(
        method_signature.return_shape.as_ref().unwrap().java_ty,
        JavaType::String
    );
}

