#[test]
fn call_graph_records_direct_and_mutual_method_edges() {
    let parsed = parse_java_source(
        r#"
class GraphCalls {
    int entry(int x) { return even(x); }
    int even(int x) { return x == 0 ? 1 : odd(x - 1); }
    int odd(int x) { return x == 0 ? 0 : even(x - 1); }
}
"#,
    );
    let resolved = resolve_program(&parsed.program, parsed.diagnostics);
    let graph = new_java2rust::usage::build_call_graph(&resolved.program);

    let entry = new_java2rust::usage::CallableKey::Method {
        type_name: "GraphCalls".to_string(),
        method_name: "entry".to_string(),
    };
    let even = new_java2rust::usage::CallableKey::Method {
        type_name: "GraphCalls".to_string(),
        method_name: "even".to_string(),
    };
    let odd = new_java2rust::usage::CallableKey::Method {
        type_name: "GraphCalls".to_string(),
        method_name: "odd".to_string(),
    };

    assert!(graph.edges.iter().any(|edge| {
        edge.caller == entry
            && edge.callee == even
            && edge.kind == new_java2rust::usage::CallGraphEdgeKind::DirectMethodCall
    }));
    assert!(graph.edges.iter().any(|edge| {
        edge.caller == even
            && edge.callee == odd
            && edge.kind == new_java2rust::usage::CallGraphEdgeKind::DirectMethodCall
    }));
    assert!(graph.edges.iter().any(|edge| {
        edge.caller == odd
            && edge.callee == even
            && edge.kind == new_java2rust::usage::CallGraphEdgeKind::DirectMethodCall
    }));
}

#[test]
fn callable_fallibility_plan_propagates_over_call_graph() {
    let parsed = parse_java_source(
        r#"
class FallibleCalls {
    int entry(int x) { return leaf(x); }
    int leaf(int x) { return x; }
}
"#,
    );
    let resolved = resolve_program(&parsed.program, parsed.diagnostics);
    let graph = new_java2rust::usage::build_call_graph(&resolved.program);
    let mut facts = FactSet::default();
    facts.method_effect_facts.push(MethodEffectFact {
        method: FactMethodKey {
            type_name: "FallibleCalls".to_string(),
            method_name: "leaf".to_string(),
        },
        receiver_mutability: ReceiverMutabilityFact::Unknown,
        return_nullability: NullabilityState::Unknown,
        thrown: vec![JavaType::Unknown("IllegalStateException".to_string())],
        provenance: FactProvenance::ParsedSource,
    });

    let fallibility = plan_program_fallibility(&resolved.program, &graph, &facts);
    let entry = new_java2rust::usage::CallableKey::Method {
        type_name: "FallibleCalls".to_string(),
        method_name: "entry".to_string(),
    };
    let leaf = new_java2rust::usage::CallableKey::Method {
        type_name: "FallibleCalls".to_string(),
        method_name: "leaf".to_string(),
    };

    assert!(fallibility.returns_result(&leaf));
    assert!(fallibility.returns_result(&entry));
    assert!(fallibility.solve_iterations() >= 2);
}

#[test]
fn loop_liveness_keeps_owned_value_live_across_back_edge() {
    let translation = translate_source(
        r#"
class LoopLivenessAudit {
    String last = "";

    void add(String value) {
        last = value;
    }

    void run(String value, int n) {
        while (n > 0) {
            add(value);
            n--;
        }
    }
}
"#,
    );

    assert!(
        !translation.diagnostics.has_errors(),
        "{:?}\n{}",
        translation.diagnostics,
        translation.rust
    );
    assert!(
        translation.rust.contains("self.add(value.clone()"),
        "{}",
        translation.rust
    );
    let lower_source = include_str!("../src/lower.rs");
    let liveness_source = include_str!("../src/liveness.rs");
    assert!(lower_source.contains("liveness: &'a crate::liveness::LivenessAnalysis"));
    assert!(lower_source.contains("LivenessAnalysis::for_body"));
    // The textual-suffix scan is gone, and so is the block-wide union that
    // replaced it: a block whose statements the analysis never saw now gets a
    // real analysis built for it (`liveness_covering_block`), so the fallback
    // stays per-statement instead of collapsing to one set for the whole block.
    assert!(!lower_source.contains("fn statement_suffix_read_names"));
    assert!(lower_source.contains("fn liveness_covering_block"));
    // No name-set approximation of the move relation survives on `LowerCtx`.
    assert!(!lower_source.contains("later_read_names"));
    assert!(!lower_source.contains("later_mutated_names"));
    assert!(liveness_source.contains("pub fn live_out_for"));
    assert!(liveness_source.contains("pub struct Binding"));
    assert!(liveness_source.contains("fn loop_fixpoint"));

    cargo_check_generated_modules(
        "loop_liveness_keeps_owned_value_live_across_back_edge",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

