#[test]
fn borrowed_external_facade_return_recovers_owned_value_before_erasure() {
    let facts = parse_external_pack_manifest(
        r#"
external-pack apache.arrow VectorSchemaRoot rust-crate-mapping mapped target=arrow_facade
external-pack apache.arrow Schema rust-crate-mapping mapped target=arrow_facade
external-pack apache.arrow FieldVector rust-crate-mapping mapped target=arrow_facade
external-pack-object apache.arrow VectorSchemaRoot concrete
external-pack-object apache.arrow Schema concrete
external-pack-object apache.arrow FieldVector concrete
external-pack-capability apache.arrow VectorSchemaRoot clone=true final=true
external-pack-capability apache.arrow Schema clone=true final=true
external-pack-capability apache.arrow FieldVector clone=true final=true
external-pack-api apache.arrow VectorSchemaRoot getSchema mapped getter read-only definitely-non-null args=0 return=Schema rust=get_schema rust-return=&Schema
external-pack-api apache.arrow VectorSchemaRoot getVector mapped getter read-only maybe-null args=1 return=FieldVector rust=get_vector rust-return=Option<&FieldVector>
external-pack-argument apache.arrow VectorSchemaRoot getVector 0 definitely-non-null read-only borrowed type=String
"#,
    )
    .facts;
    let source = r#"
class BorrowedArrowGetterReturn {
    void run(VectorSchemaRoot root) {
        Object schema = root.getSchema();
        Object vector = root.getVector("id");
        root.close();
    }
}
"#;
    let mut effective_facts = new_java2rust::stdlib::rust_stdlib_signature_facts();
    effective_facts.extend_from(facts.clone());
    let parsed = parse_java_source(source);
    let resolved = resolve_program_with_source_program_and_facts(
        &parsed.program,
        parsed.diagnostics,
        &parsed.program,
        &effective_facts,
    );
    let representations = plan_representations(&resolved.program, &effective_facts);
    let usage = analyze_usage_with_facts(&resolved.program, &effective_facts);
    let signatures = solve_signatures_with_facts(
        &resolved.program,
        &representations,
        &usage,
        &effective_facts,
    );
    let ty = &resolved.program.types[0];
    let method = match &ty.members[0] {
        Member::Method(method) => method,
        _ => panic!("expected method"),
    };
    let local_plans = signatures.method_local_shapes_or_empty(ty, method);
    assert!(
        local_plans.iter().any(|local| {
            local.name == "vector"
                && matches!(local.java_ty, JavaType::Named { ref name, .. } if name == "Object")
        }),
        "{local_plans:?}"
    );
    assert!(
        local_plans
            .iter()
            .filter(|local| local.name == "vector")
            .all(|local| matches!(local.java_ty, JavaType::Named { ref name, .. } if name == "Object")),
        "{local_plans:?}"
    );
    let vector_shape = signatures.required_local_shape(local_plans, "vector");
    assert_eq!(vector_shape.dispatch, DispatchShape::ErasedObject);
    assert_eq!(vector_shape.view, ViewShape::ErasedObjectView);
    assert!(
        matches!(
            vector_shape.optional_element_type(),
            Some(JavaType::Named { name, .. }) if name == "Object"
        ),
        "{vector_shape:?}"
    );

    let translation = translate_source_with_facts(source, &facts);

    assert!(
        translation
            .rust
            .contains("Box::new(arrow_facade::get_schema(root).clone()) as Box<dyn std::any::Any>"),
        "{}",
        translation.rust
    );
    assert!(
        translation.rust.contains(
            "arrow_facade::get_vector(root, \"id\").map(|value| Box::new(value.clone()) as Box<dyn std::any::Any>)"
        ),
        "{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "borrowed_external_facade_return_recovers_owned_value_before_",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: format!(
                r#"
pub mod arrow_facade {{
    #[derive(Clone, Copy)]
    pub struct VectorSchemaRoot;
    #[derive(Clone)]
    pub struct Schema;
    #[derive(Clone)]
    pub struct FieldVector;

    static SCHEMA: Schema = Schema;
    static FIELD_VECTOR: FieldVector = FieldVector;

    impl VectorSchemaRoot {{
        pub fn close(&self) {{}}
    }}

    pub fn get_schema(_root: VectorSchemaRoot) -> &'static Schema {{
        &SCHEMA
    }}

    pub fn get_vector<T0>(_root: VectorSchemaRoot, _arg0: T0) -> Option<&'static FieldVector> {{
        Some(&FIELD_VECTOR)
    }}
}}

pub use arrow_facade::{{FieldVector, Schema}};

{}
"#,
                translation.rust
            ),
            tests: "",
        }],
    );
}

