#[test]
fn stdlib_signature_facts_drive_math_max_owned_arg_shapes() {
    let facts = new_java2rust::stdlib::rust_stdlib_signature_facts();
    let signatures = SignaturePlan::default();
    let mut types = TypeEnv::new();
    types.insert_static_type_alias("Math", "java.lang.Math");
    types.insert_local("left", JavaType::Primitive(PrimitiveType::Int));
    types.insert_local("right", JavaType::Primitive(PrimitiveType::Int));

    let receiver = Expr::Var("Math".to_string());
    let args = vec![
        Expr::Var("left".to_string()),
        Expr::Var("right".to_string()),
    ];
    let shapes = match plan_call_arguments_with_facts_and_args(
        Some(&receiver),
        "max",
        None,
        &args,
        &signatures,
        &facts,
        &types,
    ) {
        ArgumentLoweringPlan::Shaped(shapes) => shapes,
        plan => panic!("Math.max should use owned numeric ABI facts, got {plan:?}"),
    };

    assert_eq!(shapes.len(), 2);
    assert_eq!(shapes[0].java_ty, JavaType::Primitive(PrimitiveType::Int));
    assert_eq!(shapes[0].ownership, OwnershipShape::CopyValue);
    assert_eq!(shapes[1].java_ty, JavaType::Primitive(PrimitiveType::Int));
    assert_eq!(shapes[1].ownership, OwnershipShape::CopyValue);

    let target =
        plan_call_target_with_facts_and_arity(Some(&receiver), "max", 2, None, &facts, &types);
    assert!(
        matches!(
            target,
            CallTargetPlan::NativeJavaStatic {
                method: NativeJavaStaticMethod::MathMax {
                    primitive: PrimitiveType::Int,
                },
            }
        ),
        "Math.max ABI facts should shape arguments without bypassing native max rendering: {target:?}"
    );

    let target =
        plan_call_target_with_facts_and_arity(Some(&receiver), "pow", 2, None, &facts, &types);
    assert!(
        matches!(
            target,
            CallTargetPlan::NativeJavaStatic {
                method: NativeJavaStaticMethod::MathPow,
            }
        ),
        "Math.pow should use native math rendering instead of generated facade support: {target:?}"
    );

    let external_index = facts.external_lookup_index();
    let long_int_args = vec![
        Expr::Var("left_long".to_string()),
        Expr::Var("right".to_string()),
    ];
    types.insert_local("left_long", JavaType::Primitive(PrimitiveType::Long));
    let floor_mod_target = plan_call_target_with_external_index_and_args(
        Some(&receiver),
        "floorMod",
        &long_int_args,
        None,
        &facts,
        &external_index,
        &types,
    );
    assert!(
        matches!(
            floor_mod_target,
            CallTargetPlan::NativeJavaStatic {
                method: NativeJavaStaticMethod::MathFloorMod {
                    primitive: PrimitiveType::Long,
                    return_primitive: PrimitiveType::Int,
                },
            }
        ),
        "Math.floorMod(long,int) should keep Java's int return overload: {floor_mod_target:?}"
    );
    assert_eq!(
        native_java_call_lowered_type(&floor_mod_target),
        Some(LoweredType::from_java(JavaType::Primitive(
            PrimitiveType::Int
        )))
    );

    let long_long_args = vec![
        Expr::Var("left_long".to_string()),
        Expr::Var("right_long".to_string()),
    ];
    types.insert_local("right_long", JavaType::Primitive(PrimitiveType::Long));
    let floor_div_target = plan_call_target_with_external_index_and_args(
        Some(&receiver),
        "floorDiv",
        &long_long_args,
        None,
        &facts,
        &external_index,
        &types,
    );
    assert_eq!(
        native_java_call_lowered_type(&floor_div_target),
        Some(LoweredType::from_java(JavaType::Primitive(
            PrimitiveType::Long
        )))
    );
    assert_eq!(
        native_java_call_lowered_type(&CallTargetPlan::NativeJavaStatic {
            method: NativeJavaStaticMethod::DoubleParseDouble,
        }),
        Some(LoweredType::from_java(JavaType::Primitive(
            PrimitiveType::Double
        )))
    );
}

#[test]
fn stdlib_known_math_return_fallback_uses_argument_types() {
    let math = JavaType::Named {
        name: "Math".to_string(),
        args: Vec::new(),
    };
    let strict_math = JavaType::Named {
        name: "StrictMath".to_string(),
        args: Vec::new(),
    };

    assert_eq!(
        new_java2rust::stdlib::known_external_method_return_type_for_call(
            Some(&math),
            "round",
            &[JavaType::Primitive(PrimitiveType::Float)],
        ),
        Some(JavaType::Primitive(PrimitiveType::Int))
    );
    assert_eq!(
        new_java2rust::stdlib::known_external_method_return_type_for_call(
            Some(&math),
            "round",
            &[JavaType::Primitive(PrimitiveType::Double)],
        ),
        Some(JavaType::Primitive(PrimitiveType::Long))
    );
    assert_eq!(
        new_java2rust::stdlib::known_external_method_return_type_for_call(
            Some(&strict_math),
            "round",
            &[JavaType::Primitive(PrimitiveType::Float)],
        ),
        Some(JavaType::Primitive(PrimitiveType::Int))
    );
    assert_eq!(
        new_java2rust::stdlib::known_external_method_return_type_for_call(
            Some(&math),
            "abs",
            &[JavaType::Primitive(PrimitiveType::Long)],
        ),
        Some(JavaType::Primitive(PrimitiveType::Long))
    );
    assert_eq!(
        new_java2rust::stdlib::known_external_method_return_type_for_call(
            Some(&math),
            "floorMod",
            &[
                JavaType::Primitive(PrimitiveType::Long),
                JavaType::Primitive(PrimitiveType::Int),
            ],
        ),
        Some(JavaType::Primitive(PrimitiveType::Int))
    );
}

