#[test]
fn stdlib_signature_facts_drive_jdk_io_byte_buffer_slice_shapes() {
    let facts = new_java2rust::stdlib::rust_stdlib_signature_facts();
    let signatures = SignaturePlan::default();
    let mut types = TypeEnv::new();
    types.insert_local(
        "input",
        JavaType::Named {
            name: "InputStream".to_string(),
            args: Vec::new(),
        },
    );
    types.insert_local(
        "output",
        JavaType::Named {
            name: "BufferedOutputStream".to_string(),
            args: Vec::new(),
        },
    );
    types.insert_local(
        "exact_output",
        JavaType::Named {
            name: "JavaIoOutputStream".to_string(),
            args: Vec::new(),
        },
    );
    types.insert_local(
        "buffer",
        JavaType::Array(Box::new(JavaType::Primitive(PrimitiveType::Byte))),
    );
    types.insert_local("offset", JavaType::Primitive(PrimitiveType::Int));
    types.insert_local("size", JavaType::Primitive(PrimitiveType::Int));

    let read_args = vec![
        Expr::Var("buffer".to_string()),
        Expr::Var("offset".to_string()),
        Expr::Var("size".to_string()),
    ];
    let read_shapes = match plan_call_arguments_with_facts_and_args(
        Some(&Expr::Var("input".to_string())),
        "read",
        None,
        &read_args,
        &signatures,
        &facts,
        &types,
    ) {
        ArgumentLoweringPlan::Shaped(shapes) => shapes,
        plan => panic!("InputStream.read should use mutable byte-slice ABI facts, got {plan:?}"),
    };
    assert_eq!(read_shapes.len(), 3);
    assert_eq!(read_shapes[0].ownership, OwnershipShape::MutableBorrow);
    assert_eq!(read_shapes[0].mutability, MutabilityShape::Mutable);
    assert_eq!(read_shapes[0].view, ViewShape::Slice);
    assert_eq!(
        read_shapes[0].java_ty,
        JavaType::Array(Box::new(JavaType::Primitive(PrimitiveType::Byte)))
    );
    assert!(external_call_returns_rust_result(
        Some(&Expr::Var("input".to_string())),
        "read",
        read_args.len(),
        &facts,
        &types,
        None
    ));

    let write_args = vec![
        Expr::Var("buffer".to_string()),
        Expr::Var("offset".to_string()),
        Expr::Var("size".to_string()),
    ];
    let write_shapes = match plan_call_arguments_with_facts_and_args(
        Some(&Expr::Var("output".to_string())),
        "write",
        None,
        &write_args,
        &signatures,
        &facts,
        &types,
    ) {
        ArgumentLoweringPlan::Shaped(shapes) => shapes,
        plan => panic!("OutputStream.write should use shared byte-slice ABI facts, got {plan:?}"),
    };
    assert_eq!(write_shapes.len(), 3);
    assert_eq!(write_shapes[0].ownership, OwnershipShape::SharedBorrow);
    assert_eq!(write_shapes[0].view, ViewShape::Slice);
    assert_eq!(
        write_shapes[0].java_ty,
        JavaType::Array(Box::new(JavaType::Primitive(PrimitiveType::Byte)))
    );
    assert!(external_call_returns_rust_result(
        Some(&Expr::Var("output".to_string())),
        "write",
        write_args.len(),
        &facts,
        &types,
        None
    ));

    let output_stream_write_bytes_key = CallableKey::method_with_params(
        "java.io.OutputStream",
        "write",
        Staticness::Unknown,
        vec![TypePattern::Exact(TypeKey {
            type_name: "byte[]".to_string(),
        })],
    );
    let output_stream_write_int_key = CallableKey::method_with_params(
        "java.io.OutputStream",
        "write",
        Staticness::Unknown,
        vec![TypePattern::Exact(TypeKey {
            type_name: "int".to_string(),
        })],
    );

    let write_one_bytes = vec![Expr::Var("buffer".to_string())];
    let write_one_bytes_shapes = match plan_call_arguments_with_facts_and_args(
        Some(&Expr::Var("output".to_string())),
        "write",
        None,
        &write_one_bytes,
        &signatures,
        &facts,
        &types,
    ) {
        ArgumentLoweringPlan::Shaped(shapes) => shapes,
        plan => panic!("OutputStream.write(byte[]) should use typed byte-slice ABI, got {plan:?}"),
    };
    assert_eq!(write_one_bytes_shapes.len(), 1);
    assert_eq!(
        write_one_bytes_shapes[0].ownership,
        OwnershipShape::SharedBorrow
    );
    assert_eq!(write_one_bytes_shapes[0].view, ViewShape::Slice);
    assert_eq!(
        write_one_bytes_shapes[0].java_ty,
        JavaType::Array(Box::new(JavaType::Primitive(PrimitiveType::Byte)))
    );
    assert!(matches!(
        plan_call_expr(
            Some(&Expr::Var("output".to_string())),
            "write",
            &write_one_bytes,
            None,
            &facts,
            &types
        ),
        CallExprPlan::Target(CallTargetPlan::ExternalFacadeReceiver { ref rust_path, .. })
            if rust_path == "OutputStream::write_1"
    ));
    assert!(matches!(
        plan_call_expr(
            Some(&Expr::Var("exact_output".to_string())),
            "write",
            &write_one_bytes,
            None,
            &facts,
            &types
        ),
        CallExprPlan::Target(CallTargetPlan::ExternalFacadeReceiver { ref rust_path, .. })
            if rust_path == "OutputStream::write_1"
    ));

    let write_one_int = vec![Expr::Var("size".to_string())];
    let write_one_int_shapes = match plan_call_arguments_with_facts_and_args(
        Some(&Expr::Var("output".to_string())),
        "write",
        None,
        &write_one_int,
        &signatures,
        &facts,
        &types,
    ) {
        ArgumentLoweringPlan::Shaped(shapes) => shapes,
        plan => panic!("OutputStream.write(int) should use typed primitive ABI, got {plan:?}"),
    };
    assert_eq!(write_one_int_shapes.len(), 1);
    assert_eq!(write_one_int_shapes[0].ownership, OwnershipShape::CopyValue);
    assert_eq!(
        write_one_int_shapes[0].java_ty,
        JavaType::Primitive(PrimitiveType::Int)
    );
    assert!(matches!(
        plan_call_expr(
            Some(&Expr::Var("output".to_string())),
            "write",
            &write_one_int,
            None,
            &facts,
            &types
        ),
        CallExprPlan::Target(CallTargetPlan::ExternalFacadeReceiver { ref rust_path, .. })
            if rust_path == "OutputStream::write_int"
    ));

    assert_eq!(
        facts
            .facade_abi_for_call(
                &output_stream_write_bytes_key,
                &[JavaType::Array(Box::new(JavaType::Primitive(
                    PrimitiveType::Byte
                )))]
            )
            .expect("typed byte-array write ABI")
            .rust_path,
        "OutputStream::write_1"
    );
    assert_eq!(
        facts
            .facade_abi_for_call(
                &output_stream_write_int_key,
                &[JavaType::Primitive(PrimitiveType::Int)]
            )
            .expect("typed int write ABI")
            .rust_path,
        "OutputStream::write_int"
    );
}

#[test]
fn stdlib_signature_facts_include_java_optional_rust_abi_slots() {
    let facts = new_java2rust::stdlib::rust_stdlib_signature_facts();
    let is_present_key = CallableKey::method("Optional", "isPresent", Staticness::Unknown, 0);
    let get_key = CallableKey::method("java.util.Optional", "get", Staticness::Unknown, 0);
    let or_else_key = CallableKey::method("Optional", "orElse", Staticness::Unknown, 1);

    let is_present = facts
        .facade_abi_for_key(&is_present_key)
        .expect("Optional.isPresent should have an Option::is_some ABI fact");
    assert_eq!(is_present.args, Vec::<FacadeSlot>::new());
    assert_eq!(is_present.return_slot, FacadeSlot::Owned);

    let get = facts
        .facade_abi_for_key(&get_key)
        .expect("java.util.Optional.get should have an Option::as_ref ABI fact");
    assert_eq!(get.args, Vec::<FacadeSlot>::new());
    assert_eq!(get.return_slot, FacadeSlot::Borrowed);

    let or_else = facts
        .facade_abi_for_key(&or_else_key)
        .expect("Optional.orElse should have an Option::unwrap_or ABI fact");
    assert_eq!(or_else.args, vec![FacadeSlot::Owned]);
    assert_eq!(or_else.return_slot, FacadeSlot::Owned);
}

