#[test]
fn stream_lambda_lowers_split_length_and_integer_parse_in_nullable_map() {
    let mut env = TypeEnv::new();
    env.insert_local("values", list_java_type(JavaType::String));
    let expr = parse_expr(
        "values.stream().map(value -> { String[] pieces = value.split(\",\"); if (pieces.length != 3) { return null; } return Integer.parseInt(pieces[1]); }).filter(Objects::nonNull).collect(Collectors.toList())",
    );

    let plan = build_stream_plan(&expr, &env, &FactSet::default()).unwrap();
    let lowered = render_stream_plan_with_context(
        &plan,
        RustExpr::Var("values".to_string()),
        StreamRenderContext::empty(),
    )
    .unwrap();

    assert!(matches!(
        plan.ops.as_slice(),
        [
            StreamOp::Map { .. },
            StreamOp::Filter(FilterPlan::NonNull { .. })
        ]
    ));
    assert_eq!(
        emit::emit_expr(&lowered.expr),
        "values.iter().map(|value| { let pieces = java_string_split(&value, \",\".to_string(), 0); if (pieces.len() as i32) != 3 { None } else { Some(pieces[1 as usize].parse::<i32>().map_err(|err| JavaException::from_display(\"NumberFormatException\", err)).unwrap_or_else(|ex| panic!(\"uncaught Java exception: {:?}\", ex))) } }).filter_map(|item| item).collect::<Vec<_>>()"
    );
    assert!(matches!(
        lowered.expr,
        RustExpr::MethodCall { receiver, method, args }
            if method == "collect::<Vec<_>>"
                && args.is_empty()
                && matches!(receiver.as_ref(), RustExpr::MethodCall { method, args, .. }
                    if method == "filter_map" && args.len() == 1)
    ));
    let mut stream_env = ShapeEnv::new();
    stream_env.insert_local_shape(
        "values",
        RustSlotShape::conservative(list_java_type(JavaType::String)),
    );
    let lowered_with_context = render_stream_plan_with_context(
        &plan,
        RustExpr::Var("values".to_string()),
        StreamRenderContext::new(&stream_env),
    )
    .unwrap();
    assert_eq!(
        emit::emit_expr(&lowered_with_context.expr),
        "values.iter().map(|value| { let pieces = java_string_split(&value, \",\".to_string(), 0); if (pieces.len() as i32) != 3 { None } else { Some(pieces[1 as usize].parse::<i32>().map_err(|err| JavaException::from_display(\"NumberFormatException\", err)).unwrap_or_else(|ex| panic!(\"uncaught Java exception: {:?}\", ex))) } }).filter_map(|item| item).collect::<Vec<_>>()"
    );
    let mut env = ShapeEnv::new();
    env.insert_local_shape(
        "vid_map_p_b",
        RustSlotShape::conservative(JavaType::Named {
            name: "VidMapPB".to_string(),
            args: Vec::new(),
        }),
    );
    assert_eq!(
        emit_stream_lambda_body_with_context(
            &parse_expr("vid_map_p_b.getContigsList()"),
            "partition",
            StreamLambdaValue::BorrowedItem,
            StreamRenderContext::new(&env),
        ),
        Some("vid_map_p_b.get_contigs_list()".to_string())
    );
    assert_eq!(
        emit_stream_lambda_body_with_context(
            &parse_expr("constants.DELIMITER"),
            "partition",
            StreamLambdaValue::BorrowedItem,
            StreamRenderContext::empty(),
        ),
        Some("Constants::DELIMITER".to_string())
    );
    assert_eq!(
        emit_stream_lambda_body_with_context(
            &parse_expr("constants.DELIMITER"),
            "partition",
            StreamLambdaValue::BorrowedItem,
            StreamRenderContext::new(&env),
        ),
        Some("Constants::DELIMITER".to_string())
    );
    let stream_lowering_source = include_str!("../src/stream_lowering.rs");
    let field_access_branch = stream_lowering_source
        .split("Expr::FieldAccess(receiver, field) =>")
        .nth(1)
        .and_then(|tail| tail.split("Expr::ArrayAccess(array, index)").next())
        .expect("stream lambda field access branch should be present");
    assert!(
        field_access_branch.contains("emit_stream_lambda_member_access_through_plan_expr"),
        "{field_access_branch}"
    );
    assert!(
        field_access_branch.contains("owner_associated_path_projection(&owner, field)")
            && !field_access_branch.contains("render_stream_static_member_path(&owner, field)")
            && !field_access_branch.contains(
                "stream_lambda_rendered_expr(\n                        render_stream_static_member_path"
            ),
        "stream static constant field access should stay structured in lambda lowering"
    );
    assert!(
        stream_lowering_source.contains("crate::access_lowering::lower_field_access_with_facts"),
        "stream member access should render through shared access lowering"
    );
    let planned_member_access = stream_lowering_source
        .split("fn emit_stream_lambda_member_access_through_plan_expr")
        .nth(1)
        .and_then(|tail| tail.split("fn stream_raw_expr").next())
        .expect("stream member access plan helper should remain discoverable");
    assert!(
        planned_member_access.contains("emit_stream_lambda_receiver_with_locals_expr")
            && planned_member_access.contains(") -> Option<(RustExpr, u8)>")
            && !planned_member_access.contains("crate::emit::emit_expr")
            && !planned_member_access
                .contains("rendered_projection_or_raw_leaf(&lowered_receiver)"),
        "stream member access planning should pass structured receivers into shared access lowering"
    );
    let stream_raw_expr_source = stream_lowering_source
        .split("fn stream_raw_expr")
        .nth(1)
        .and_then(|tail| tail.split("pub fn render_stream_plan_with_context").next())
        .expect("stream raw expression helper should remain discoverable");
    assert!(
        stream_lowering_source.contains("let expr = stream_raw_expr(raw);")
            && stream_lowering_source.contains("crate::emit::expr_precedence(&expr)")
            && stream_raw_expr_source.contains("raw_java_static_member_access(raw)")
            && stream_raw_expr_source.contains("owner_associated_path_projection(owner, member)")
            && stream_raw_expr_source.contains("java_static_owner_ident(owner)")
            && stream_raw_expr_source.contains("rendered_plus_expr_projection_or_raw_leaf(raw)")
            && !stream_raw_expr_source.contains("RustExpr::Raw(raw.to_string())")
            && !stream_raw_expr_source.contains("matches!(recovered.unshaped(), RustExpr::Raw(_))")
            && !stream_raw_expr_source.contains("rendered_projection_or_raw_leaf(raw)")
            && !stream_lowering_source.contains(
                "Expr::Raw(raw) => stream_lambda_rendered_expr(render_stream_raw_expr(raw), 12)"
            ),
        "stream lambda raw ingress should recover parseable leaves structurally with only narrow static-member raw recovery"
    );
}

#[test]
fn stream_lambda_string_char_at_uses_signature_index_slot() {
    let mut env = TypeEnv::new();
    env.insert_local("values", list_java_type(JavaType::String));
    env.insert_local("index", JavaType::Primitive(PrimitiveType::Int));
    let expr = parse_expr(
        "values.stream().map(value -> value.charAt(index)).collect(Collectors.toList())",
    );

    let plan = build_stream_plan(&expr, &env, &FactSet::default()).unwrap();
    let mut shape_env = ShapeEnv::new();
    shape_env.insert_local("value", JavaType::String);
    shape_env.insert_local("index", JavaType::Primitive(PrimitiveType::Int));
    let facts = new_java2rust::stdlib::rust_stdlib_signature_facts();
    assert!(matches!(
        new_java2rust::call_plan::plan_call_arguments_with_facts_and_args(
            Some(&parse_expr("value")),
            "char_at",
            None,
            &[parse_expr("index")],
            &new_java2rust::signature::SignaturePlan::default(),
            &facts,
            shape_env.type_env(),
        ),
        new_java2rust::call_plan::ArgumentLoweringPlan::Slotted(slots)
            if slots == vec![new_java2rust::conversion_plan::Slot::Index]
    ));
    let lowered = render_stream_plan_with_context(
        &plan,
        RustExpr::Var("values".to_string()),
        StreamRenderContext::empty(),
    )
    .unwrap();

    assert_eq!(
        emit::emit_expr(&lowered.expr),
        "values.iter().map(|value| value.chars().nth((index) as usize).expect(\"Java string index out of bounds\")).collect::<Vec<_>>()"
    );
    assert!(matches!(
        lowered.expr,
        RustExpr::MethodCall { receiver, method, args }
            if method == "collect::<Vec<_>>"
                && args.is_empty()
                && matches!(receiver.as_ref(), RustExpr::MethodCall { method, args, .. }
                    if method == "map" && args.len() == 1)
    ));
}

#[test]
fn stream_plan_lowers_collectors_to_map_terminal() {
    let mut env = TypeEnv::new();
    env.insert_local("values", list_java_type(JavaType::String));
    let expr = parse_expr("values.stream().collect(Collectors.toMap(v -> v, v -> v.length()))");

    let plan = build_stream_plan(&expr, &env, &FactSet::default()).unwrap();
    let lowered = render_stream_plan_with_context(
        &plan,
        RustExpr::Var("values".to_string()),
        StreamRenderContext::empty(),
    )
    .unwrap();

    assert_eq!(
        emit::emit_expr(&lowered.expr),
        "values.iter().map(|v| ((*v).clone(), v.len() as i32)).collect::<std::collections::HashMap<_, _>>()"
    );
    let RustExpr::MethodCall {
        receiver,
        method,
        args,
    } = &lowered.expr
    else {
        panic!("Collectors.toMap should lower to a collect method call");
    };
    assert_eq!(method, "collect::<std::collections::HashMap<_, _>>");
    assert!(args.is_empty());
    let RustExpr::MethodCall {
        method: map_method,
        args: map_args,
        ..
    } = receiver.as_ref()
    else {
        panic!("Collectors.toMap should lower through a map call");
    };
    assert_eq!(map_method, "map");
    let [
        RustExpr::Closure {
            body: RustClosureBody::Expr(body),
            ..
        },
    ] = map_args.as_slice()
    else {
        panic!("Collectors.toMap map call should contain one expression closure");
    };
    let RustExpr::Tuple(items) = body.as_ref() else {
        panic!("Collectors.toMap map closure should return a tuple");
    };
    let [key_expr, RustExpr::Cast { .. }] = items.as_slice() else {
        panic!("Collectors.toMap map closure should return key/value projections");
    };
    assert_eq!(emit::emit_expr(key_expr), "(*v).clone()");
    assert!(
        !matches!(key_expr, RustExpr::Raw(_)),
        "Collectors.toMap identity key should remain structured"
    );
    let LoweredType::Slot(shape) = lowered.actual else {
        panic!("Collectors.toMap should lower as a concrete map slot");
    };
    assert_eq!(
        shape.java_ty,
        JavaType::Named {
            name: "Map".to_string(),
            args: vec![JavaType::String, JavaType::Primitive(PrimitiveType::Int)],
        }
    );
}

#[test]
fn stream_plan_lowers_collectors_to_map_owned_source_identity_without_deref_clone() {
    let parsed = parse_java_source(
        r#"
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

class OwnedToMapSource {
    Map<Item, Integer> index() {
        return items().stream().collect(Collectors.toMap(item -> item, item -> item.getLength()));
    }

    List<Item> items() {
        return null;
    }
}

class Item {
    int getLength() {
        return 0;
    }
}
"#,
    );
    let resolved = resolve_program(&parsed.program, parsed.diagnostics);
    let ty = &resolved.program.types[0];
    let method = ty
        .members
        .iter()
        .find_map(|member| match member {
            Member::Method(method) if method.name == "index" => Some(method),
            _ => None,
        })
        .unwrap();
    let Some(Stmt::Return(Some(expr))) = method.body.as_ref().unwrap().statements.first() else {
        panic!("expected stream return");
    };
    let env = TypeEnv::new();

    let plan = build_stream_plan(expr, &env, &resolved.facts).unwrap();
    let lowered = render_stream_plan_with_context(
        &plan,
        RustExpr::Raw("self.items()".to_string()),
        StreamRenderContext::empty(),
    )
    .unwrap();

    let raw = emit::emit_expr(&lowered.expr);
    assert_eq!(
        raw,
        "self.items().into_iter().map(|item| (item, item.get_length())).collect::<std::collections::HashMap<_, _>>()"
    );
    assert!(matches!(
        lowered.expr,
        RustExpr::MethodCall { receiver, method, args }
            if method == "collect::<std::collections::HashMap<_, _>>"
                && args.is_empty()
                && matches!(receiver.as_ref(), RustExpr::MethodCall { method, args, .. }
                    if method == "map" && args.len() == 1)
    ));
    assert!(!raw.contains("(*item).clone()"), "{raw}");
}

