#[test]
fn field_nullability_join_handles_conflicting_evidence() {
    use new_java2rust::lattice::field_nullability_join;

    assert_eq!(
        field_nullability_join(
            NullabilityState::DefinitelyNull,
            NullabilityState::DefinitelyNonNull,
        ),
        NullabilityState::MaybeNull
    );
    assert_eq!(
        field_nullability_join(
            NullabilityState::Unknown,
            NullabilityState::DefinitelyNonNull
        ),
        NullabilityState::Unknown
    );
    assert_eq!(
        field_nullability_join(NullabilityState::Unknown, NullabilityState::DefinitelyNull),
        NullabilityState::MaybeNull
    );
}

#[test]
fn core_signature_lattice_merges_satisfy_join_laws() {
    fn assert_join_laws<T>(values: &[T], join: fn(T, T) -> T)
    where
        T: Clone + Eq + std::fmt::Debug,
    {
        for value in values {
            assert_eq!(join(value.clone(), value.clone()), *value);
        }

        for left in values {
            for right in values {
                assert_eq!(
                    join(left.clone(), right.clone()),
                    join(right.clone(), left.clone())
                );
                let merged = join(left.clone(), right.clone());
                assert_eq!(join(merged.clone(), left.clone()), merged);
                assert_eq!(join(merged.clone(), right.clone()), merged);
            }
        }

        for left in values {
            for middle in values {
                for right in values {
                    assert_eq!(
                        join(join(left.clone(), middle.clone()), right.clone()),
                        join(left.clone(), join(middle.clone(), right.clone()))
                    );
                }
            }
        }
    }

    assert_join_laws(
        &[
            OwnershipShape::SharedBorrow,
            OwnershipShape::MutableBorrow,
            OwnershipShape::CopyValue,
            OwnershipShape::Owned,
        ],
        |left, right| merge_ownership_requirement_policy(Some(left), right).kept,
    );
    assert_join_laws(
        &[
            ViewShape::Str,
            ViewShape::DynTraitView,
            ViewShape::ErasedObjectView,
            ViewShape::Native,
        ],
        |left, right| merge_view_requirement_policy(Some(left), right).kept,
    );
    assert_join_laws(
        &[
            DispatchShape::DynTrait {
                trait_name: "Animal".to_string(),
            },
            DispatchShape::BoxedDynTrait {
                trait_name: "Animal".to_string(),
            },
            DispatchShape::ErasedObject,
            DispatchShape::Concrete,
        ],
        |left, right| merge_dispatch_requirement_policy(Some(left), right).kept,
    );
    assert_join_laws(
        &[
            NullabilityState::DefinitelyNonNull,
            NullabilityState::Unknown,
            NullabilityState::DefinitelyNull,
            NullabilityState::MaybeNull,
        ],
        |left, right| merge_storage_nullability_requirement_policy(Some(left), right).kept,
    );
}

// ---------------------------------------------------------------------------
// Constants declared in available source
// ---------------------------------------------------------------------------

/// Group 3 of [0031](../claude_audits/done/0031-stubbed-constant-census.md): a
/// constant whose owner is a *context-summary* source — the corpus's own
/// dependency set — has its value right there in the parsed declaration, and it
/// was being dropped. The facade then emitted `compile_error!` for a value the
/// translation had already read.
///
/// The values below are checked against the Java oracle in the audit: `javac`
/// on both files prints `9,-1.0,BCF\2\2`, and so does the translation.
#[test]
fn static_final_constants_from_summary_sources_carry_their_declared_values() {
    let summary = r#"
package htsjdk.variant.bcf2;

public class BcfFormat {
    public static final int SIZEOF_BCF_HEADER = 9;
    public static final int UNKNOWN_SEQUENCE_LENGTH = -1;
    public static final double NO_LOG10_PERROR = -1.0;
    public static final boolean DEBUG_MODE_ENABLED = false;
    public static final String MAGIC = "BCF";
    public static final long BIG = 1L << 40;
    /** Derived from an earlier constant of the same owner. */
    public static final int HEADER_PLUS_ONE = SIZEOF_BCF_HEADER + 1;
    /** Not a constant expression: the value really is unknown. */
    public static final int RUNTIME = computed();

    static int computed() { return 3; }
}
"#;
    let source = r#"
import htsjdk.variant.bcf2.BcfFormat;

public class Reader {
    public static int headerSize() { return BcfFormat.SIZEOF_BCF_HEADER; }
    public static int unknownLength() { return BcfFormat.UNKNOWN_SEQUENCE_LENGTH; }
    public static double noError() { return BcfFormat.NO_LOG10_PERROR; }
    public static boolean debug() { return BcfFormat.DEBUG_MODE_ENABLED; }
    public static String magic() { return BcfFormat.MAGIC; }
    public static long big() { return BcfFormat.BIG; }
    public static int plusOne() { return BcfFormat.HEADER_PLUS_ONE; }
}
"#;
    let translation = translate_source_with_context_summary_sources(
        source,
        &[summary.to_string()],
        &FactSet::default(),
    );

    for expected in [
        "pub const SIZEOF_BCF_HEADER: i32 = 9;",
        "pub const UNKNOWN_SEQUENCE_LENGTH: i32 = -1;",
        "pub const NO_LOG10_PERROR: f64 = -1.0;",
        "pub const DEBUG_MODE_ENABLED: bool = false;",
        "pub const MAGIC: &'static str = \"BCF\";",
        "pub const BIG: i64 = 1099511627776i64;",
        "pub const HEADER_PLUS_ONE: i32 = 10;",
    ] {
        assert!(
            translation.rust.contains(expected),
            "missing {expected:?}:\n{}",
            translation.rust
        );
    }

    assert!(
        !translation.rust.contains("has no modeled value"),
        "a constant whose value is in the summary source must not be stubbed:\n{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "static_final_constants_from_summary_sources_carry_their_decl",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

/// The other half of the same rule: a value that genuinely is not a constant
/// expression must stay loud rather than acquire a plausible zero.
#[test]
fn non_constant_static_final_initializers_stay_unmodelled() {
    let summary = r#"
package dep;

public class Runtime {
    public static final int RUNTIME = computed();
    static int computed() { return 3; }
}
"#;
    let source = r#"
import dep.Runtime;

public class Caller {
    public static int value() { return Runtime.RUNTIME; }
}
"#;
    let translation = translate_source_with_context_summary_sources(
        source,
        &[summary.to_string()],
        &FactSet::default(),
    );

    assert!(
        translation.rust.contains("has no modeled value"),
        "a non-constant initializer must not be folded into a value:\n{}",
        translation.rust
    );
    assert!(
        !translation.rust.contains("pub const RUNTIME: i32 = 0;"),
        "the whole point of 0031 is that this is never a plain zero:\n{}",
        translation.rust
    );
}

// ---------------------------------------------------------------------------
// Assignment evaluation order
// ---------------------------------------------------------------------------

/// Java evaluates an assignment's target subexpressions before its right-hand
/// side; Rust evaluates the value first
/// ([0026](../claude_audits/done/0026-assignment-evaluation-order-differs-from-java.md)).
///
/// The case pinned here is the one that is easy to miss: the index has no side
/// effect of its own, and the **value** is what changes what it denotes. The
/// behaviour is checked against the Java oracle by
/// `tests/differential/EvalOrder.java`; this pins that the hoist is emitted at
/// all, which reading the result cannot show — `b[0]` is `0` either way, and
/// the defect is that a *different element* was written.
#[test]
fn a_side_effecting_value_hoists_a_stable_looking_index() {
    let translation = translate_source(
        r#"
public class Order {
    public static int run() {
        int[] b = new int[3];
        int m = 0;
        b[m] = m++;
        return b[1];
    }
}
"#,
    );

    assert!(
        translation
            .rust
            .contains("let __java_assignment_index = m as usize;"),
        "the index must be evaluated before the value:\n{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "a_side_effecting_value_hoists_a_stable_looking_index",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

/// A literal index needs no hoist, however side-effecting the value is: nothing
/// can change what it denotes, so the extra temporary would be pure noise.
#[test]
fn a_literal_index_is_not_hoisted_for_a_side_effecting_value() {
    let translation = translate_source(
        r#"
public class Order {
    public static int run() {
        int[] b = new int[3];
        int m = 0;
        b[0] = m++;
        return b[0];
    }
}
"#,
    );

    assert!(
        !translation.rust.contains("__java_assignment_index"),
        "a literal index is stable across evaluating the value:\n{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "a_literal_index_is_not_hoisted_for_a_side_effecting_value",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

/// The assignment place is a *field*, and the array access is a subexpression
/// of it — so none of the ordered-*array*-assignment paths recognise it.
#[test]
fn a_field_place_hoists_its_receivers_array_index() {
    let translation = translate_source(
        r#"
public class Order {
    int field = 0;

    public static int run() {
        Order[] arr = new Order[2];
        arr[0] = new Order();
        arr[1] = new Order();
        int j = 0;
        arr[j++].field = j;
        return arr[0].field;
    }
}
"#,
    );

    assert!(
        translation
            .rust
            .contains("let __java_assignment_index: i32 = {"),
        "the place's index must be evaluated before the value:\n{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("arr[__java_assignment_index as usize].field ="),
        "the write must go through the hoisted index:\n{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "a_field_place_hoists_its_receivers_array_index",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

/// A *ragged* two-dimensional assignment hoists both indices.
///
/// The ndarray-backed numeric case was already ordered; a `String[][]` is a
/// `Vec<Vec<T>>` and fell through to the plain path, where Rust reads the value
/// before either index is evaluated
/// ([0026](../claude_audits/done/0026-assignment-evaluation-order-differs-from-java.md)).
///
/// Pinned textually rather than against the Java oracle because the output for
/// this shape does not compile for an unrelated reason — the declared type, the
/// initialiser and the read projection pick three different carriers
/// ([0038](../claude_audits/done/0038-two-dimensional-object-array-carrier-disagrees.md)).
#[test]
fn ragged_two_dimensional_assignment_hoists_both_indices() {
    let translation = translate_source(
        r#"
public class Ragged {
    static int[] counter = new int[1];
    static int bump() { counter[0] = counter[0] + 1; return counter[0] - 1; }

    public static void run() {
        String[][] g = new String[2][];
        g[0] = new String[2];
        g[1] = new String[2];
        g[bump()][bump()] = "v";
    }
}
"#,
    );

    assert!(
        translation
            .rust
            .contains("let __java_assignment_row = Self::bump() as usize;"),
        "the row index must be evaluated first:\n{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("let __java_assignment_col = Self::bump() as usize;"),
        "then the column index, before the value:\n{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("g[__java_assignment_row][__java_assignment_col] ="),
        "and the write goes through both temporaries:\n{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "ragged_two_dimensional_assignment_hoists_both_indices",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

/// The numeric case keeps the ndarray projection: the ragged path must decline
/// where ndarray is the right carrier, or it would rewrite working output.
#[test]
fn ndarray_backed_two_dimensional_assignment_keeps_its_own_ordered_path() {
    let translation = translate_source(
        r#"
public class Numeric {
    static int[] counter = new int[1];
    static int bump() { counter[0] = counter[0] + 1; return counter[0] - 1; }

    public static void run() {
        int[][] g = new int[2][2];
        g[bump()][bump()] = 7;
    }
}
"#,
    );

    assert!(
        translation
            .rust
            .contains("g[[__java_assignment_row, __java_assignment_col]] ="),
        "a primitive 2D array stays on the ndarray projection:\n{}",
        translation.rust
    );
}

/// Overloads reached through a context-summary source must get the same Rust
/// name from every lowering path.
///
/// The static path resolved them (`pick_int`, `pick_string`) because it
/// re-solves signatures on an isolated one-type program, which assigns Rust
/// names. The instance path read `MethodDecl::rust_name` directly — and context
/// and summary programs never went through the naming pass, so it was `None`
/// and `source_method_rust_name` fell back to the bare snake-cased Java name,
/// collapsing both overloads onto `inst`.
///
/// Two answers to one question, which is what
/// [0009](../claude_audits/done/0009-overload-identity-collapses-onto-rust-name.md)
/// is about. The naming pass was already correct; it was not applied here.
#[test]
fn summary_source_overloads_get_one_rust_name_from_every_path() {
    let summary = r#"
package dep;

public class Util {
    public static int pick(int x) { return x + 1; }
    public static int pick(String s) { return s.length() + 100; }
    public int inst(int x) { return x + 2; }
    public int inst(String s) { return s.length() + 200; }
}
"#;
    let source = r#"
import dep.Util;

public class Caller {
    public static int statics() { return Util.pick(1) + Util.pick("ab"); }
    public static int instances(Util u) { return u.inst(1) + u.inst("ab"); }
}
"#;
    let translation = translate_source_with_context_summary_sources(
        source,
        &[summary.to_string()],
        &FactSet::default(),
    );

    for expected in [
        "Util::pick_int(1)",
        "Util::pick_string(",
        "u.inst_int(1)",
        "u.inst_string(",
        "fn inst_int<T0>",
        "fn inst_string<T0>",
    ] {
        assert!(
            translation.rust.contains(expected),
            "missing {expected:?}:\n{}",
            translation.rust
        );
    }
    // The collapsed spelling must not survive anywhere: it is the defect.
    assert!(
        !translation.rust.contains("u.inst(") && !translation.rust.contains("Util::pick("),
        "an overload still collapsed onto its bare name:\n{}",
        translation.rust
    );
    assert!(
        !translation.rust.contains("fn inst<T0>"),
        "the erased-object facade must not collapse overloads either:\n{}",
        translation.rust
    );
}

/// Java's `Object.equals` **is** reference identity unless a class overrides it.
///
/// Shared immutable source classes now lower inherited equality through handle
/// identity. This warning still matters for source classes that are not in an
/// implemented shared tier, where lowering would otherwise compare fields.
#[test]
fn inherited_equals_on_a_source_class_is_reported_as_identity() {
    let translation = translate_source(
        r#"
public class Eq {
    static class Key {
        int v;
        Key(int v) { this.v = v; }
        void set(int value) { this.v = value; }
    }

    public static boolean run() {
        Key a = new Key(5);
        Key b = new Key(5);
        return a.equals(b);
    }
}
"#,
    );

    assert!(
        translation
            .diagnostics
            .has_code("java_inherited_equals_identity"),
        "an inherited equals must be reported:\n{:?}",
        translation.diagnostics
    );
}

/// The negative, which is what makes the diagnostic worth having: a class that
/// *does* override `equals` is behaving correctly and must not be reported.
#[test]
fn an_overridden_equals_is_not_reported_as_identity() {
    let translation = translate_source(
        r#"
public class Eq {
    static final class Key {
        final int v;
        Key(int v) { this.v = v; }
        public boolean equals(Object other) { return other instanceof Key; }
    }

    public static boolean run() {
        Key a = new Key(5);
        Key b = new Key(5);
        return a.equals(b);
    }
}
"#,
    );

    assert!(
        !translation
            .diagnostics
            .has_code("java_inherited_equals_identity"),
        "an overridden equals is correct and must not be reported:\n{:?}",
        translation.diagnostics
    );
}

#[test]
fn an_overloaded_equals_is_still_reported_as_inherited_object_identity() {
    let translation = translate_source(
        r#"
public class Eq {
    static final class Key {
        final int v;
        Key(int v) { this.v = v; }
        public boolean equals(Key other) { return other != null && other.v == v; }
    }

    public static boolean run() {
        Key a = new Key(5);
        Key b = new Key(5);
        return a.equals(b);
    }
}
"#,
    );

    assert!(
        translation
            .diagnostics
            .has_code("java_inherited_equals_identity"),
        "equals(Key) is an overload, so Object.equals is still inherited:\n{:?}",
        translation.diagnostics
    );
}

/// A subclass inherits its superclass's override, so it must not be reported
/// either — the walk has to follow `extends`, not just look at the class.
#[test]
fn an_equals_inherited_from_a_source_superclass_is_not_reported() {
    let translation = translate_source(
        r#"
public class Eq {
    static class Base {
        public boolean equals(Object other) { return other instanceof Base; }
    }

    static class Derived extends Base { }

    public static boolean run() {
        Derived a = new Derived();
        Derived b = new Derived();
        return a.equals(b);
    }
}
"#,
    );

    assert!(
        !translation
            .diagnostics
            .has_code("java_inherited_equals_identity"),
        "an equals inherited from a source superclass is still an override:\n{:?}",
        translation.diagnostics
    );
}

/// A type whose source the translation is reading is not an unmodelled import.
///
/// The facade emitter synthesised a generic arity stub for it —
/// `pub fn pick<R, T0>(_arg0: T0) -> R { unimplemented!(…) }` under the
/// **unsuffixed** name — while the call sites, which do resolve the overload,
/// emitted `pick_int` and `pick_string`. The facade provided neither name, so
/// the program failed `E0599`. That was the half of
/// [0009](../claude_audits/done/0009-overload-identity-collapses-onto-rust-name.md)
/// left open after the call-site naming was fixed: a *fourth* place that names
/// methods, disagreeing with the other three.
#[test]
fn a_summary_source_type_gets_no_unmodelled_import_stub() {
    let summary = r#"
package dep;

public class Util {
    public static int pick(int x) { return x + 1; }
    public static int pick(String s) { return s.length() + 100; }
}
"#;
    let source = r#"
import dep.Util;

public class Caller {
    public static int run() { return Util.pick(1) + Util.pick("ab"); }
}
"#;
    let translation = translate_source_with_context_summary_sources(
        source,
        &[summary.to_string()],
        &FactSet::default(),
    );

    assert!(
        !translation.rust.contains("imported static method pick"),
        "a type whose source is read must not get an unmodelled-import stub:\n{}",
        translation.rust
    );
    // The type itself is still declared — an importing file names it.
    assert!(
        translation.rust.contains("pub type Util = DepUtil;"),
        "the type must still be emitted:\n{}",
        translation.rust
    );
    // And the call sites keep the resolved overload names.
    assert!(
        translation.rust.contains("Util::pick_int(1)")
            && translation.rust.contains("Util::pick_string("),
        "call sites must keep their resolved names:\n{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("pub fn pick_int<T0>(_arg0: T0) -> i32")
            && translation
                .rust
                .contains("pub fn pick_string<T0>(_arg0: T0) -> i32"),
        "source-summary static methods must be provided as static facade methods:\n{}",
        translation.rust
    );
    assert!(
        !translation.rust.contains("pub fn pick_int<T0>(&self")
            && !translation.rust.contains("pub fn pick_string<T0>(&self"),
        "source-summary static methods must not be emitted as instance methods:\n{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "a_summary_source_type_gets_no_unmodelled_import_stub",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust.clone(),
            tests: "",
        }],
    );
}

